def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    if n == 0:
        return []
    order = sorted(set(a))
    rank = {v: i + 1 for i, v in enumerate(order)}
    m = len(order)
    bit = [0] * (m + 1)

    def add(i: int, delta: int) -> None:
        while i <= m:
            bit[i] += delta
            i += i & -i

    def prefix(i: int) -> int:
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    ans = [0] * n
    for i in range(n):
        if i > 0:
            add(rank[a[i - 1]], 1)
            out = i - k - 1
            if out >= 0:
                add(rank[a[out]], -1)
        r = rank[a[i]]
        ans[i] = prefix(m) - prefix(r)
    return ans
